mapper.select:
select  from mst_ext_system s left join mst_cust c on c.cust_id = s.cust_id
s.use_yn = #{useYn}
order by s.system_type, s.system_cd

mapper.update:
update mst_ext_system
   set system_nm = #{f.systemNm}, system_type = #{f.systemType}, conn_mode = #{f.connMode}, cust_id = #{f.custId}, use_yn = #{f.useYn},
       remark = #{f.remark}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where system_id = #{id} and row_ver = #{f.rowVer}

update if_code_map
   set ext_code = #{f.extCode}, int_code = #{f.intCode}, use_yn = #{f.useYn},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where code_map_id = #{id} and row_ver = #{f.rowVer}

mapper.select:
select  from mst_ext_id_map m join mst_ext_system s on s.system_id = m.system_id
 where m.entity_type = #{entityType} and m.internal_id = #{internalId}
 order by m.use_yn desc, s.system_type, s.system_cd, m.map_id

mapper.update:
update mst_ext_id_map
   set external_id = #{f.externalId}, external_nm = #{f.externalNm}, use_yn = #{f.useYn},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where map_id = #{id} and row_ver = #{f.rowVer}
